package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathUtils_factorialDouble_TriageGen2Test {

    private static final double DELTA = 1e-10;











    @Test
    public void testFactorialDouble_LargePositive() {
        // n = 22 is not 21, calls factorial(22)
        // Note: factorial(int) returns long, so it might overflow if n is too large,
        // but for n=22, 22! = 1.1240007277776077e+21. 
        // However, since the method calls factorial(n) which returns long, 
        // we test a value that fits in long or is handled by the logic.
        // Given the implementation, if n > 20, factorial(n) might return overflowed long.
        // We test the branch logic coverage.
        double result = MathUtils.factorialDouble(22);
        // The result is essentially bounded by what the long factorial(22) returns.
        // This test ensures the "n != 21" branch is covered.
        org.junit.Assert.assertTrue(result >= 0);
    }
}
